#include "core.hpp"
#include <fstream>
#include <iostream>
#include <windows.h>
using namespace scratcher;
static int checks=0;
static void check(bool condition,const char*label){++checks;if(!condition)throw std::runtime_error(label);}
int main(){try{
 auto dir=executableDir()/"test-fixtures";std::filesystem::create_directories(dir);
 // x64: mov eax,42; ret, padded so instruction lookahead remains mapped.
 auto raw=dir/"return42.bin";std::vector<uint8_t> data(64,0x90);data[0]=0xb8;data[1]=42;data[2]=data[3]=data[4]=0;data[5]=0xc3;const char text[]="Scratcher fixture string";std::memcpy(data.data()+20,text,sizeof(text));{std::ofstream out(raw,std::ios::binary);out.write((char*)data.data(),data.size());}
 Engine engine;Tools tools(engine);auto metadata=engine.open(raw);check(metadata["entry"]=="0x1000","raw entry");check(metadata["size"]==64,"mapped length");auto asmRows=engine.disassemble(0x1000,2);check(asmRows.size()==2,"instruction count");check(asmRows[0].length==5,"mov length");check(asmRows[1].mnemonic=="RET"||asmRows[1].mnemonic=="ret","return decode");auto dc=engine.decompile(0x1000);check(dc["code"].get<std::string>().find("42")!=std::string::npos||dc["code"].get<std::string>().find("0x2a")!=std::string::npos,"native constant decompilation");check(engine.decompile(0x1000)["cached"]==true,"decompiler cache");check(engine.listStrings()["total"].get<size_t>()>=1,"strings scan");check(engine.readBytes(0x1000,6)["hex"]=="b82a000000c3","mapped bytes");engine.rename(0x1000,"return42");check(engine.listFunctions()["items"][0]["name"]=="return42","rename indexed function");auto project=dir/"fixture.scratcher";engine.saveProject(project);engine.loadProject(project);check(engine.listFunctions()["items"][0]["name"]=="return42","project round trip");check(engine.decompile(0x1000)["code"].get<std::string>().find("return42")!=std::string::npos,"renamed decompiler output");
 auto init=tools.rpc({{"jsonrpc","2.0"},{"id",1},{"method","initialize"},{"params",{{"protocolVersion","2025-11-25"}}}});check(init["result"]["serverInfo"]["name"]=="Scratcher","MCP initialize");check(tools.localList().size()>=37,"MCP tool discovery");tools.rpc({{"jsonrpc","2.0"},{"method","notifications/initialized"}});auto response=tools.rpc({{"jsonrpc","2.0"},{"id",2},{"method","tools/call"},{"params",{{"name","read_bytes"},{"arguments",{{"address","0x1000"},{"count",6}}}}}});check(response["result"]["isError"]==false,"MCP tool call");auto invalid=tools.rpc({{"jsonrpc","2.0"},{"id",3},{"method","tools/call"},{"params",{{"name","read_bytes"},{"arguments",{{"address","0x1000"},{"count",-1}}}}}});check(invalid["result"]["isError"]==true,"MCP argument validation");check(tools.rpc({{"jsonrpc","2.0"},{"method","notifications/initialized"}}).is_null(),"MCP notification silence");
 bool rejected=false;try{engine.readBytes(0xffff0000,5);}catch(...){rejected=true;}check(rejected,"unmapped bytes rejected");
 auto truncated=dir/"truncated.exe";{std::ofstream out(truncated,std::ios::binary);out<<"MZ";}rejected=false;try{engine.open(truncated);}catch(...){rejected=true;}check(rejected,"truncated PE rejected");check(engine.binary()->size()==64,"failed open preserves session");
 auto pe=engine.open(executableDir()/"scratcher_tests.exe");check(pe["format"]=="PE","real PE loader");check(pe["function_count"].get<size_t>()>10,"PE unwind function index");check(pe["import_count"].get<size_t>()>0,"PE import index");
 // Minimal valid little-endian ELF64 executable with one PT_LOAD.
 auto elf=dir/"fixture.elf";std::vector<uint8_t> image(4096,0);auto write=[&](size_t off,auto value){std::memcpy(image.data()+off,&value,sizeof(value));};std::memcpy(image.data(),"\x7f" "ELF",4);image[4]=2;image[5]=1;image[6]=1;write(16,uint16_t(2));write(18,uint16_t(62));write(20,uint32_t(1));write(24,uint64_t(0x400080));write(32,uint64_t(64));write(52,uint16_t(64));write(54,uint16_t(56));write(56,uint16_t(1));write(64,uint32_t(1));write(68,uint32_t(5));write(72,uint64_t(0));write(80,uint64_t(0x400000));write(96,uint64_t(image.size()));write(104,uint64_t(image.size()));std::memcpy(image.data()+128,data.data(),6);{std::ofstream out(elf,std::ios::binary);out.write((char*)image.data(),image.size());}check(engine.open(elf)["format"]=="ELF","ELF loader");check(engine.decompile(0x400080)["code"].get<std::string>().find("0x2a")!=std::string::npos||engine.decompile(0x400080)["code"].get<std::string>().find("42")!=std::string::npos,"ELF native decompilation");
 check(engine.open(raw,0x1000,32)["bits"]==32,"raw x86 loader");check(engine.decompile(0x1000)["code"].get<std::string>().find("42")!=std::string::npos||engine.decompile(0x1000)["code"].get<std::string>().find("0x2a")!=std::string::npos,"x86 native decompilation");
 std::cout<<"PASS: "<<checks<<" native loader, decompiler, project, and MCP checks\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}catch(...){std::cerr<<"Unexpected native engine exception\n";return 1;}}
